@namespace sv_d9e6e8f5850c425da771573a98234bb0.Components.Pages.Catalog

<nav class="catalog-pagination" aria-label="Product pagination">
    <button class="page-btn"
            disabled="@(CurrentPage <= 1)"
            @onclick="@(() => GoToPage(CurrentPage - 1))">
        Previous
    </button>

    @foreach (var page in PageNumbers)
    {
        <button class="page-btn @(page == CurrentPage ? "active" : "")"
                @onclick="@(() => GoToPage(page))">
            @page
        </button>
    }

    <button class="page-btn"
            disabled="@(CurrentPage >= TotalPages)"
            @onclick="@(() => GoToPage(CurrentPage + 1))">
        Next
    </button>
</nav>

@code {
    [Parameter]
    public int CurrentPage { get; set; }

    [Parameter]
    public int TotalPages { get; set; }

    [Parameter]
    public EventCallback<int> OnPageChanged { get; set; }

    private IEnumerable<int> PageNumbers => Enumerable.Range(1, TotalPages);

    private async Task GoToPage(int page)
    {
        if (page >= 1 && page <= TotalPages)
        {
            await OnPageChanged.InvokeAsync(page);
        }
    }
}

.catalog-pagination {
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 0.25rem;
    margin-top: 2rem;
    padding: 1rem 0;
}

.page-btn {
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    background: #fff;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.9rem;
    min-width: 2.5rem;
    text-align: center;
}

.page-btn:hover:not(:disabled):not(.active) {
    background: #f0f0f0;
}

.page-btn.active {
    background: #0066cc;
    color: #fff;
    border-color: #0066cc;
}

.page-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

