@page "/catalog"
@namespace sv_d9e6e8f5850c425da771573a98234bb0.Components.Pages.Catalog
@using sv_d9e6e8f5850c425da771573a98234bb0
@rendermode InteractiveServer
@inject IProductService ProductService

<PageTitle>Product Catalog</PageTitle>

<div class="catalog-layout">
    <CatalogFilters Categories="@_categories"
                    OnApplyFilters="HandleApplyFilters"
                    OnClearFilters="HandleClearFilters" />

    <main class="catalog-main">
        @if (_isLoading)
        {
            <div class="catalog-state">
                <p>Loading products...</p>
            </div>
        }
        else if (_errorMessage is not null)
        {
            <div class="catalog-state catalog-error">
                <p>@_errorMessage</p>
                <button @onclick="LoadProducts">Try Again</button>
            </div>
        }
        else if (_result is null || _result.Items.Count == 0)
        {
            <div class="catalog-state">
                <p>No products found. Try adjusting your filters.</p>
            </div>
        }
        else
        {
            <CatalogToolbar SortBy="@_sortBy"
                            TotalCount="@_result.TotalCount"
                            Page="@_currentPage"
                            PageSize="@PageSize"
                            OnSortChanged="HandleSortChanged" />

            <ProductGrid Products="@_result.Items"
                         OnProductSelected="HandleProductSelected"
                         OnAddToCart="HandleAddToCart" />

            <CatalogPagination CurrentPage="@_currentPage"
                               TotalPages="@TotalPages"
                               OnPageChanged="HandlePageChanged" />
        }
    </main>
</div>

@code {
    private const int PageSize = 12;

    private List<string> _categories = [];
    private PagedResult<Product>? _result;
    private ProductFilter _currentFilter = new(null, null, null, false);
    private string _sortBy = "price_asc";
    private int _currentPage = 1;
    private bool _isLoading = true;
    private string? _errorMessage;

    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    private int TotalPages => _result is null || _result.TotalCount == 0
        ? 1
        : (int)Math.Ceiling((double)_result.TotalCount / PageSize);

    protected override async Task OnInitializedAsync()
    {
        try
        {
            _categories = await ProductService.GetCategoriesAsync();
            await LoadProducts();
        }
        catch (Exception ex)
        {
            _errorMessage = $"Failed to load catalog: {ex.Message}";
            _isLoading = false;
        }
    }

    private async Task LoadProducts()
    {
        _isLoading = true;
        _errorMessage = null;

        try
        {
            _result = await ProductService.SearchAsync(_currentFilter, _sortBy, _currentPage, PageSize);
        }
        catch (Exception ex)
        {
            _errorMessage = $"Failed to load products: {ex.Message}";
        }
        finally
        {
            _isLoading = false;
        }
    }

    private async Task HandleApplyFilters(ProductFilter filter)
    {
        _currentFilter = filter;
        _currentPage = 1;
        await LoadProducts();
    }

    private async Task HandleClearFilters()
    {
        _currentFilter = new ProductFilter(null, null, null, false);
        _currentPage = 1;
        await LoadProducts();
    }

    private async Task HandleSortChanged(string sortBy)
    {
        _sortBy = sortBy;
        _currentPage = 1;
        await LoadProducts();
    }

    private async Task HandlePageChanged(int page)
    {
        _currentPage = page;
        await LoadProducts();
    }

    private async Task HandleProductSelected(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private Task HandleAddToCart(Product product)
    {
        // Add to cart logic can be handled by a parent or a cart service
        return Task.CompletedTask;
    }
}

.catalog-layout {
    display: grid;
    grid-template-columns: 25% 1fr;
    min-height: calc(100vh - 4rem);
}

.catalog-main {
    padding: 1.5rem;
}

.catalog-state {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 4rem 2rem;
    color: #666;
    font-size: 1.1rem;
}

.catalog-state button {
    margin-top: 1rem;
    padding: 0.5rem 1rem;
    background: #0066cc;
    color: #fff;
    border: none;
    border-radius: 4px;
    cursor: pointer;
}

.catalog-error {
    color: #c00;
}

